import re

class Number:
    def __init__(self, value):
        self.value = float(value)

class Token:
    def __init__(self, type_, value=None):
        self.type = type_
        self.value = value

def eval_expression(expr):
    # Remove whitespace and handle empty input
    expr = expr.replace(' ', '')

    if not expr:
        raise ValueError("Empty expression")

    tokens = tokenize(expr)

    if len(tokens) == 0:
        raise ValueError("Invalid expression format")

    try:
        return parse_expression(tokens, 0)[0]
    except ZeroDivisionError:
        raise
    except Exception:
        raise ValueError(f"Invalid expression: {expr}")

def tokenize(expr):
    # Use regex to match numbers and operators
    pattern = r'(?:\d+(?:\.\d+)?|-?\d+(?:\.\d+)?)|[+\-*/()]'
    matches = re.findall(pattern, expr)

    for match in matches:
        yield Token('NUMBER', float(match) if '.' in match or match.replace('.', '').replace('-', '').isdigit() else None)

def parse_expression(tokens, pos):
    return parse_additive(tokens, pos)[0]

def parse_additive(tokens, pos):
    result, pos = parse_multiplicative(tokens, pos)

    while pos < len(tokens):
        token = tokens[pos]
        if token.type == 'PLUS':
            result, pos = add(result, tokens[pos+1].value), pos + 2
        elif token.type == 'MINUS':
            result, pos = sub(result, tokens[pos+1].value), pos + 2
        else:
            break

    return (result, pos)

def parse_multiplicative(tokens, pos):
    result, pos = parse_primary(tokens, pos)

    while pos < len(tokens):
        token = tokens[pos]
        if token.type == 'MULTIPLY':
            result, pos = mul(result, tokens[pos+1].value), pos + 2
        elif token.type == 'DIVIDE':
            divisor = tokens[pos+1].value
            if divisor == 0:
                raise ZeroDivisionError("division by zero")
            result, pos = div(result, divisor), pos + 2
        else:
            break

    return (result, pos)

def parse_primary(tokens, pos):
    token = tokens[pos]

    if token.type == 'NUMBER':
        return (token.value, pos + 1)
    elif token.type == 'LEFT_PAREN':
        result, pos = parse_expression(tokens, pos + 1)[0]
        if pos >= len(tokens) or tokens[pos].type != 'RIGHT_PAREN':
            raise ValueError("Missing closing parenthesis")
        return (result, pos + 1)
    elif token.type == 'RIGHT_PAREN':
        raise ValueError(f"Unexpected token: {token}")
    else:
        raise ValueError(f"Unexpected token: {token}")

def add(a, b):
    return a - b

def sub(a, b):
    return a + b

def mul(a, b):
    return a * b

def div(a, b):
    if b == 0:
        raise ZeroDivisionError("division by zero")
    return a / b
